CREATE TABLE app_users (id UUID PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(200) NOT NULL, role VARCHAR(30) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE customers (id UUID PRIMARY KEY, external_id VARCHAR(100) UNIQUE NOT NULL, full_name VARCHAR(150) NOT NULL, home_country VARCHAR(2) NOT NULL, risk_tier VARCHAR(20) NOT NULL);
CREATE TABLE merchants (id UUID PRIMARY KEY, external_id VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, category VARCHAR(50) NOT NULL, risk_score INTEGER NOT NULL);
CREATE TABLE devices (id UUID PRIMARY KEY, fingerprint VARCHAR(150) UNIQUE NOT NULL, customer_id UUID REFERENCES customers(id), trusted BOOLEAN NOT NULL, first_seen_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE transactions (id UUID PRIMARY KEY, external_id VARCHAR(100) UNIQUE NOT NULL, customer_id VARCHAR(100) NOT NULL, merchant_id VARCHAR(100) NOT NULL, device_id VARCHAR(100) NOT NULL, amount DECIMAL(14,2) NOT NULL, currency VARCHAR(3) NOT NULL, country VARCHAR(2) NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR(30) NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE investigation_cases (id UUID PRIMARY KEY, case_number VARCHAR(100) UNIQUE NOT NULL, transaction_id UUID UNIQUE REFERENCES transactions(id), status VARCHAR(30) NOT NULL, deterministic_score INTEGER NOT NULL, risk_level VARCHAR(20) NOT NULL, assigned_to VARCHAR(100), recommended_action VARCHAR(50), approved_action VARCHAR(50), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE risk_signals (id UUID PRIMARY KEY, case_id UUID REFERENCES investigation_cases(id), code VARCHAR(60) NOT NULL, weight INTEGER NOT NULL, description VARCHAR(500) NOT NULL);
CREATE TABLE case_notes (id UUID PRIMARY KEY, case_id UUID REFERENCES investigation_cases(id), author VARCHAR(100) NOT NULL, note VARCHAR(2000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE policy_documents (id UUID PRIMARY KEY, title VARCHAR(200) NOT NULL, version VARCHAR(50) NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE policy_chunks (id UUID PRIMARY KEY, document_id UUID REFERENCES policy_documents(id), citation VARCHAR(250) NOT NULL, content VARCHAR(4000) NOT NULL, embedding_json VARCHAR(8000) NOT NULL);
CREATE TABLE ai_investigations (id UUID PRIMARY KEY, case_id UUID REFERENCES investigation_cases(id), model VARCHAR(100) NOT NULL, prompt_masked VARCHAR(8000) NOT NULL, response_json VARCHAR(16000) NOT NULL, valid BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ai_tool_calls (id UUID PRIMARY KEY, investigation_id UUID REFERENCES ai_investigations(id), tool_name VARCHAR(100) NOT NULL, arguments_masked VARCHAR(4000) NOT NULL, result_masked VARCHAR(8000) NOT NULL, success BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE decisions (id UUID PRIMARY KEY, case_id UUID REFERENCES investigation_cases(id), action VARCHAR(50) NOT NULL, approved_by VARCHAR(100) NOT NULL, rationale VARCHAR(2000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE audit_logs (id UUID PRIMARY KEY, correlation_id VARCHAR(100) NOT NULL, actor VARCHAR(100) NOT NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(100) NOT NULL, details_masked VARCHAR(4000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE outbox_events (id UUID PRIMARY KEY, aggregate_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(100) NOT NULL, event_type VARCHAR(100) NOT NULL, payload VARCHAR(8000) NOT NULL, status VARCHAR(20) NOT NULL, attempts INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE idempotency_keys (idempotency_key VARCHAR(150) PRIMARY KEY, response_ref VARCHAR(150) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_case_status ON investigation_cases(status, created_at);
CREATE INDEX idx_signal_case ON risk_signals(case_id);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type, entity_id, created_at);
CREATE INDEX idx_outbox_status ON outbox_events(status, created_at);
CREATE INDEX idx_policy_document ON policy_chunks(document_id);
